BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "customers" (
	"Customer ID"	TEXT,
	"Customer Name"	TEXT,
	"Segment"	TEXT,
	"Country"	TEXT,
	"City"	TEXT,
	"State"	TEXT,
	"Postal Code"	INT,
	"Region"	TEXT
);
CREATE TABLE IF NOT EXISTS "orders" (
	"Order ID"	TEXT,
	"Order Date"	TEXT,
	"Ship Date"	TEXT,
	"Ship Mode"	TEXT,
	"Customer ID"	TEXT,
	"Product ID"	TEXT,
	"Sales"	REAL,
	"Quantity"	INT,
	"Discount"	INT,
	"Profit"	REAL
);
CREATE TABLE IF NOT EXISTS "products" (
	"Product ID"	TEXT,
	"Product Name"	TEXT,
	"Category"	TEXT,
	"Sub-Category"	TEXT
);
CREATE TABLE IF NOT EXISTS "superstore_raw" (
	"Row ID"	INTEGER,
	"Order ID"	TEXT,
	"Order Date"	TEXT,
	"Ship Date"	TEXT,
	"Ship Mode"	TEXT,
	"Customer ID"	TEXT,
	"Customer Name"	TEXT,
	"Segment"	TEXT,
	"Country"	TEXT,
	"City"	TEXT,
	"State"	TEXT,
	"Postal Code"	INTEGER,
	"Region"	TEXT,
	"Product ID"	TEXT,
	"Category"	TEXT,
	"Sub-Category"	TEXT,
	"Product Name"	TEXT,
	"Sales"	REAL,
	"Quantity"	INTEGER,
	"Discount"	INTEGER,
	"Profit"	REAL
);
COMMIT;
